args.command:
echo "== application-version =="; curl -s -w '
HTTP %{http_code}
' http://host.docker.internal:3000/rest/admin/application-version --max-time 10; echo; echo "== application-configuration (grep version) =="; curl -s http://host.docker.internal:3000/rest/admin/application-configuration --max-time 10 | head -c 300; echo; echo "== package.json.bak / main.js =="; for p in /package.json.bak /main.js /assets/package.json.bak; do printf '%s -> ' "$p"; curl -s -o /dev/null -w '%{http_code}
' http://host.docker.internal:3000$p --max-time 10; done
